{
  "version": 1,
  "name": "generic-hierarchical-reduction-runtime-config",
  "divider": {
    "max_kb": 180,
    "crosscheck_policy": {
      "enabled": false,
      "bounded_raw_overlap_budget_fraction": 0.25,
      "allow_crosscheck_recursion": false
    }
  },
  "iterator_rules": {
    "evaluator_class_selection": [
      {
        "condition": "B == 0",
        "evaluator_class": "base_evaluator"
      },
      {
        "condition": "B > 0",
        "evaluator_class": "decision_evaluator"
      }
    ],
    "termination_test": {
      "metric": "aggregate_response_kb / divider.max_kb",
      "operator": "<=",
      "threshold": 1.0
    },
    "final_evaluator_class": "decision_evaluator"
  },
  "retry_and_correction_policy": {
    "max_transport_retries": 1,
    "max_corrective_attempts": 1
  },
  "response_size_rules": {
    "preferred_response_kb": 40,
    "hard_size_rule": {
      "type": "ratio_of_batch_max",
      "value": 0.5
    }
  },
  "iterator_tests": [
    "transport_success",
    "required_keys_recovery",
    "hard_size_rule"
  ],
  "evaluator_classes": {
    "base_evaluator": {
      "task": "Perform primary evidence reduction and proof generation on raw context.",
      "criteria": [
        "Operate strictly on the provided batch context.",
        "Extract minimal verifiable facts with exact source/locator provenance.",
        "Formulate discrete truth decisions backed by explicit evidence IDs.",
        "Preserve ambiguities and contradictions rather than assuming resolution."
      ],
      "response_contract": {
        "expected_type": "hierarchical_reduction_decision",
        "required_keys": [
          "response_type",
          "summarized_context",
          "proof",
          "decision"
        ]
      }
    },
    "decision_evaluator": {
      "task": "Reconcile, aggregate, and reduce prior proof-carrying decisions into higher-order synthesis.",
      "criteria": [
        "Operate strictly on prior proof-carrying decisions; do not expect raw context.",
        "Merge redundant facts and retain provenance lineage across all prior decisions.",
        "Preserve open contradictions as INDETERMINATE.",
        "Aggressively compress prose while preserving all actionable decision claims."
      ],
      "response_contract": {
        "expected_type": "hierarchical_reduction_decision",
        "required_keys": [
          "response_type",
          "summarized_context",
          "proof",
          "decision"
        ]
      }
    }
  }
}

