const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

function readJson(p) {
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

function writeJson(p, val) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify(val, null, 2) + '\n');
}

function getByteLength(val) {
  if (typeof val === 'string') return Buffer.byteLength(val, 'utf8');
  return Buffer.byteLength(JSON.stringify(val), 'utf8');
}

function sanitizeId(str) {
  return String(str).replace(/[^A-Za-z0-9._-]+/g, '_');
}

function recoverJsonPayload(text) {
  const raw = String(text || '').trim();
  try {
    return JSON.parse(raw);
  } catch (_) {}

  const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenceMatch) {
    try {
      return JSON.parse(fenceMatch[1].trim());
    } catch (_) {}
  }

  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    const candidate = raw.slice(firstBrace, lastBrace + 1);
    try {
      return JSON.parse(candidate);
    } catch (_) {}
  }
  return null;
}

function selectEvaluatorClass(iteratorRules, B) {
  const rules = iteratorRules.evaluator_class_selection || [];
  for (const r of rules) {
    const cond = String(r.condition || '').trim();
    if (cond === 'B == 0' && B === 0) return r.evaluator_class;
    if (cond === 'B > 0' && B > 0) return r.evaluator_class;
    const matchEq = cond.match(/^B\s*==\s*(\d+)$/);
    if (matchEq && B === Number(matchEq[1])) return r.evaluator_class;
    const matchGt = cond.match(/^B\s*>\s*(\d+)$/);
    if (matchGt && B > Number(matchGt[1])) return r.evaluator_class;
  }
  return B === 0 ? 'base_evaluator' : 'decision_evaluator';
}

function evaluateTermination(rule, aggregateKb, dividerMaxKb) {
  const metric = aggregateKb / dividerMaxKb;
  if (rule.operator === '<=') return metric <= rule.threshold;
  if (rule.operator === '<') return metric < rule.threshold;
  return metric <= 1.0;
}

function partitionContext(items, maxBytes) {
  const batches = [];
  let currentBatch = [];
  let currentBytes = 0;

  for (const item of items) {
    const itemBytes = getByteLength(item);
    if (currentBatch.length > 0 && currentBytes + itemBytes > maxBytes) {
      batches.push(currentBatch);
      currentBatch = [];
      currentBytes = 0;
    }
    currentBatch.push(item);
    currentBytes += itemBytes;
  }
  if (currentBatch.length > 0) {
    batches.push(currentBatch);
  }
  return batches;
}

async function executeModelCall(promptPayload) {
  const apiKey = process.env.GEMINI_API_KEY;
  const model = process.env.GEMINI_MODEL || 'gemini-2.5-flash';
  const timeoutMs = Number(process.env.GEMINI_REQUEST_TIMEOUT_MS || 180000);
  const maxOutputTokens = Number(process.env.GEMINI_MAX_OUTPUT_TOKENS || 16384);

  if (!apiKey) throw new Error('GEMINI_API_KEY environment variable is required.');

  const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`;
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-goog-api-key': apiKey
    },
    body: JSON.stringify({
      system_instruction: {
        parts: [{ text: promptPayload.system }]
      },
      contents: [
        { role: 'user', parts: [{ text: promptPayload.user }] }
      ],
      generationConfig: {
        responseMimeType: 'application/json',
        maxOutputTokens
      }
    }),
    signal: AbortSignal.timeout(timeoutMs)
  });

  const rawText = await response.text();
  let jsonBody = null;
  try {
    jsonBody = JSON.parse(rawText);
  } catch (_) {
    throw new Error(`Transport HTTP ${response.status}: non-JSON raw body returned: ${rawText.slice(0, 300)}`);
  }

  if (!response.ok) {
    throw new Error(`Transport HTTP ${response.status}: ${JSON.stringify(jsonBody.error || jsonBody)}`);
  }

  const candidate = jsonBody.candidates?.[0];
  const contentParts = candidate?.content?.parts;
  if (!Array.isArray(contentParts) || contentParts.length === 0) {
    throw new Error(`Model returned candidate with no parts: ${JSON.stringify(jsonBody)}`);
  }
  return contentParts.map(p => p.text || '').join('\n').trim();
}

async function runWorker() {
  const [, , , inputPath, outputPath] = process.argv;
  if (!inputPath || !outputPath) {
    throw new Error('Worker mode requires inputPath and outputPath arguments.');
  }
  const workerInput = readJson(path.resolve(inputPath));
  const responseText = await executeModelCall(workerInput);
  writeJson(path.resolve(outputPath), {
    raw_response: responseText
  });
}

function spawnWorkerInvocation(workerInput, inputPath, outputPath) {
  writeJson(inputPath, workerInput);
  const res = spawnSync(process.execPath, [__filename, '--worker', inputPath, outputPath], {
    cwd: process.cwd(),
    env: { ...process.env },
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024
  });
  if (res.error) throw res.error;
  if (res.status !== 0) {
    const errDetail = (res.stderr || res.stdout || `Worker exited with status ${res.status}`).trim();
    throw new Error(`Worker process failed: ${errDetail}`);
  }
  const outData = readJson(outputPath);
  return outData.raw_response;
}

function validateMechanical(recoveredJson, responseBytes, inputBatchBytes, contract, hardSizeRule) {
  const errors = [];
  if (!recoveredJson || typeof recoveredJson !== 'object') {
    errors.push('Failed to parse or recover JSON object from model output.');
    return { valid: false, errors, normalized: null };
  }

  for (const k of contract.required_keys || []) {
    if (recoveredJson[k] === undefined || recoveredJson[k] === null) {
      errors.push(`Missing required key: ${k}`);
    }
  }

  if (hardSizeRule && hardSizeRule.type === 'ratio_of_batch_max') {
    const maxAllowed = Math.floor(inputBatchBytes * Number(hardSizeRule.value));
    if (responseBytes > maxAllowed) {
      errors.push(`Response byte size ${responseBytes} exceeds hard limit ${maxAllowed} (ratio ${hardSizeRule.value} of input ${inputBatchBytes}).`);
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    normalized: recoveredJson
  };
}

function buildPrompt(evaluatorConfig, batchContext, correctiveContext = null) {
  const systemParts = [
    `Evaluator Task: ${evaluatorConfig.task}`,
    'Evaluation Criteria:',
    ...(evaluatorConfig.criteria || []).map(c => ` - ${c}`),
    `Required Response Contract Schema: ${JSON.stringify(evaluatorConfig.response_contract)}`,
    'Mechanical constraints: Return ONLY valid JSON matching the schema. No markdown fences, no extraneous conversational text.'
  ];

  const userPayload = {
    batch_context: batchContext
  };

  if (correctiveContext) {
    userPayload.corrective_action = {
      instruction: 'Your previous response failed mechanical validation. Correct ONLY the mechanical errors noted while preserving the original task and criteria.',
      prior_invalid_response: correctiveContext.prior_response,
      mechanical_errors: correctiveContext.errors
    };
  }

  return {
    system: systemParts.join('\n\n'),
    user: JSON.stringify(userPayload, null, 2)
  };
}

function executeBatchWithPolicy(batchData, evaluatorClassKey, config, workDir, batchLabel) {
  const evaluatorConfig = config.evaluator_classes[evaluatorClassKey];
  if (!evaluatorConfig) throw new Error(`Configured evaluator class not found: ${evaluatorClassKey}`);

  const maxTransportRetries = config.retry_and_correction_policy?.max_transport_retries ?? 1;
  const maxCorrectiveAttempts = config.retry_and_correction_policy?.max_corrective_attempts ?? 1;
  const hardSizeRule = config.response_size_rules?.hard_size_rule;
  const inputBatchBytes = getByteLength(batchData);

  let rawOutput = null;
  let transportAttempts = 0;
  let transportError = null;

  while (transportAttempts <= maxTransportRetries) {
    transportAttempts++;
    try {
      const inputPath = path.join(workDir, `${batchLabel}-t${transportAttempts}-in.json`);
      const outputPath = path.join(workDir, `${batchLabel}-t${transportAttempts}-out.json`);
      const prompt = buildPrompt(evaluatorConfig, batchData, null);
      rawOutput = spawnWorkerInvocation(prompt, inputPath, outputPath);
      transportError = null;
      break;
    } catch (err) {
      transportError = err;
    }
  }

  if (transportError) {
    return {
      status: 'system_failure',
      batch_label: batchLabel,
      error: transportError.message,
      evaluator_class: evaluatorClassKey,
      input_batch_bytes: inputBatchBytes
    };
  }

  let responseBytes = Buffer.byteLength(rawOutput, 'utf8');
  let recovered = recoverJsonPayload(rawOutput);
  let mechCheck = validateMechanical(recovered, responseBytes, inputBatchBytes, evaluatorConfig.response_contract, hardSizeRule);

  if (!mechCheck.valid && maxCorrectiveAttempts > 0) {
    const correctiveInputPath = path.join(workDir, `${batchLabel}-corrective-in.json`);
    const correctiveOutputPath = path.join(workDir, `${batchLabel}-corrective-out.json`);
    const correctivePrompt = buildPrompt(evaluatorConfig, batchData, {
      prior_response: rawOutput,
      errors: mechCheck.errors
    });
    try {
      rawOutput = spawnWorkerInvocation(correctivePrompt, correctiveInputPath, correctiveOutputPath);
      responseBytes = Buffer.byteLength(rawOutput, 'utf8');
      recovered = recoverJsonPayload(rawOutput);
      mechCheck = validateMechanical(recovered, responseBytes, inputBatchBytes, evaluatorConfig.response_contract, hardSizeRule);
    } catch (cErr) {
      mechCheck.errors.push(`Corrective attempt worker failure: ${cErr.message}`);
      mechCheck.valid = false;
    }
  }

  if (!mechCheck.valid) {
    return {
      status: 'mechanical_failure',
      batch_label: batchLabel,
      errors: mechCheck.errors,
      raw_output_snippet: rawOutput ? rawOutput.slice(0, 500) : null,
      evaluator_class: evaluatorClassKey,
      input_batch_bytes: inputBatchBytes
    };
  }

  return {
    status: 'success',
    batch_label: batchLabel,
    evaluator_class: evaluatorClassKey,
    response_bytes: responseBytes,
    result: mechCheck.normalized
  };
}

async function main() {
  if (process.argv[2] === '--worker') {
    await runWorker();
    return;
  }

  const configPath = path.resolve(process.env.HIERARCHICAL_CONFIG_PATH || path.join(__dirname, 'config.json'));
  const inputDataPath = path.resolve(process.env.HIERARCHICAL_INPUT_DATA || path.join(__dirname, 'input_data.json'));
  const outputDir = path.resolve(process.env.HIERARCHICAL_OUTPUT_DIR || path.join(__dirname, 'output'));
  const workDir = path.join(outputDir, 'work');
  fs.mkdirSync(workDir, { recursive: true });

  const config = readJson(configPath);
  let rawInputItems = readJson(inputDataPath);
  if (!Array.isArray(rawInputItems)) {
    rawInputItems = [rawInputItems];
  }

  const dividerMaxBytes = (config.divider?.max_kb || 180) * 1024;
  let B = 0;
  let currentWorkingItems = rawInputItems;
  const roundRecords = [];

  while (true) {
    const evaluatorClass = selectEvaluatorClass(config.iterator_rules, B);
    const batches = partitionContext(currentWorkingItems, dividerMaxBytes);
    const batchResults = [];

    for (let i = 0; i < batches.length; i++) {
      const batchData = batches[i];
      const batchLabel = `B${B}-batch-${sanitizeId(i + 1)}`;
      const outcome = executeBatchWithPolicy(batchData, evaluatorClass, config, workDir, batchLabel);
      batchResults.push(outcome);
    }

    const roundReport = {
      B,
      evaluator_class: evaluatorClass,
      batch_count: batches.length,
      outcomes: batchResults
    };
    roundRecords.push(roundReport);
    writeJson(path.join(outputDir, `round-B${B}-summary.json`), roundReport);

    const successfulPayloads = batchResults
      .filter(r => r.status === 'success')
      .map(r => r.result);

    const totalSerializedBytes = getByteLength(successfulPayloads);
    const totalKb = totalSerializedBytes / 1024;

    const isTerminated = evaluateTermination(
      config.iterator_rules.termination_test,
      totalKb,
      config.divider.max_kb
    );

    if (isTerminated) {
      const finalClass = config.iterator_rules.final_evaluator_class || 'decision_evaluator';
      const finalLabel = `final-reduction-B${B}`;
      const finalOutcome = executeBatchWithPolicy(successfulPayloads, finalClass, config, workDir, finalLabel);
      const finalArtifactPath = path.join(outputDir, 'final-evaluation.json');
      writeJson(finalArtifactPath, {
        status: finalOutcome.status,
        B_rounds_completed: B,
        final_evaluator_class: finalClass,
        aggregate_response_kb: totalKb,
        final_result: finalOutcome.result || null,
        metadata: finalOutcome
      });
      break;
    }

    currentWorkingItems = successfulPayloads;
    B++;
  }

  writeJson(path.join(outputDir, 'hierarchical-execution-summary.json'), {
    total_rounds: B + 1,
    rounds: roundRecords,
    completed_at: new Date().toISOString()
  });
}

if (require.main === module) {
  main().catch(err => {
    console.error(err);
    process.exit(1);
  });
}

module.exports = {
  recoverJsonPayload,
  selectEvaluatorClass,
  evaluateTermination,
  partitionContext,
  validateMechanical
};
